oazú","flavor":"Copoazú","stockKind":"unit"},{"key":"bolo-fruta-tamarindo","name":"Bolo de fruta · Tamarindo","category":"Bolos","price":350,"art":"bolo","description":"","group":"Bolos de fruta","variant":"Tamarindo","flavor":"Tamarindo","stockKind":"unit"},{"key":"bolo-fruta-mocochinchi","name":"Bolo de fruta · Mocochinchi","category":"Bolos","price":350,"art":"bolo","description":"","group":"Bolos de fruta","variant":"Mocochinchi","flavor":"Mocochinchi","stockKind":"unit"}]'::jsonb) LOOP
  INSERT INTO products(name,category,price,art,description,menu_key,group_name,variant,size,flavor,inventory_mode)
  VALUES(entry->>'name',entry->>'category',(entry->>'price')::integer,entry->>'art',entry->>'description',entry->>'key',entry->>'group',entry->>'variant',coalesce(entry->>'size',''),coalesce(entry->>'flavor',''),'recipe')
  RETURNING id INTO product_id_value;
  IF entry->>'stockKind'='prepared' THEN CONTINUE; END IF;
  is_mix := entry->>'stockKind'='escarcha';
  item_name := CASE WHEN is_mix THEN 'Mezcla de escarcha · '||(entry->>'flavor') ELSE entry->>'name' END;
  SELECT id INTO item_id_value FROM inventory WHERE name=item_name;
  IF item_id_value IS NULL THEN
   INSERT INTO inventory(name,unit,stock,minimum)
   VALUES(item_name,CASE WHEN is_mix THEN 'ml' ELSE 'ud' END,0,CASE WHEN is_mix THEN 1000 ELSE 5 END)
   RETURNING id INTO item_id_value;
  END IF;
  INSERT INTO recipes(product_id,item_id,quantity) VALUES(product_id_value,item_id_value,CASE WHEN is_mix THEN (entry->>'ml')::integer ELSE 1 END);
 END LOOP;
 INSERT INTO settings(key,value) VALUES('client_menu_version','flamingo-client-menu-2026-10');
END $menu$;
